/** Codes de `jeu_recompenses_catalogue` (origine 'roulette') -> icône. */
export const ICONE_PAR_CODE_LOT: Record<string, IdSegmentRoue> = {
  roulette_tampon_1: 'tampon1',
  roue_topping: 'topping',
  roulette_tampon_2: 'tampon2',
  roulette_reduction_10: 'reduc10',
  roulette_tampon_3: 'tampon3',
  roue_reduction_20: 'reduc20',
  roulette_boisson_l: 'boisson',
}

export const IDS_SEGMENTS_ROUE = Object.keys(MONO) as IdSegmentRoue[]

/** Le tracé monochrome SEUL, à poser dans un <Svg> existant (la roue). */
export function MotifRoueMono({ id, couleur }: { id: IdSegmentRoue; couleur: string }) {
  return <Path d={MONO[id]} fill={couleur} fillRule="evenodd" />
}

type Props = {
  id: IdSegmentRoue
  variante?: VarianteIcone
  /** Obligatoire en 'mono' : la couleur du tracé. Ignorée sinon. */
  couleur?: string
  taille?: number
}

/** Icône autonome, dans son propre <Svg> — listes, cérémonie de gain, notifications. */
export function IconeRoue({ id, variante = 'pastille', couleur = '#2A1D46', taille = 56 }: Props) {
  return (
    <Svg width={taille} height={taille} viewBox="0 0 96 96">
      {variante === 'mono'
        ? <Path d={MONO[id]} fill={couleur} fillRule="evenodd" />
        : MOTIFS[id][variante]}
    </Svg>
  )
}

export default IconeRoue
